-- ============================================
-- ORACLE · INVENTORY DEPARTMENT
-- 3 tables · 9 columns each · 1000 rows each
-- Run: docker exec -i oracle_db sqlplus system/root@localhost:1521/XEPDB1 < oracle_inventory.sql
-- ============================================

BEGIN EXECUTE IMMEDIATE 'DROP TABLE STOCK_MOVEMENTS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/

BEGIN EXECUTE IMMEDIATE 'DROP TABLE PRODUCTS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/

BEGIN EXECUTE IMMEDIATE 'DROP TABLE SUPPLIERS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/

CREATE TABLE suppliers (
    supplier_id      NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    supplier_name    VARCHAR2(150) NOT NULL,
    contact_person   VARCHAR2(120),
    email            VARCHAR2(150),
    phone            VARCHAR2(25),
    city             VARCHAR2(80),
    country          VARCHAR2(80),
    rating           NUMBER(3,1),
    is_active        CHAR(1) DEFAULT 'Y'
);
/

CREATE TABLE products (
    product_id     NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    product_name   VARCHAR2(200) NOT NULL,
    category       VARCHAR2(80),
    subcategory    VARCHAR2(80),
    unit_price     NUMBER(12,2),
    cost_price     NUMBER(12,2),
    weight_kg      NUMBER(8,3),
    supplier_id    NUMBER,
    is_active      CHAR(1) DEFAULT 'Y',
    CONSTRAINT fk_prod_sup FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
);
/

CREATE TABLE stock_movements (
    movement_id    NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    product_id     NUMBER,
    movement_type  VARCHAR2(30),
    quantity       NUMBER(10),
    warehouse      VARCHAR2(100),
    movement_date  DATE NOT NULL,
    reference_no   VARCHAR2(60),
    unit_cost      NUMBER(12,2),
    total_cost     NUMBER(14,2),
    CONSTRAINT fk_stock_prod FOREIGN KEY (product_id) REFERENCES products(product_id)
);
/

/

/

COMMIT;
/